import{z as n,x as i,o as B,c as l,q as e,j as t,D as a,d as r,s as o,S as s}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"次优理论","description":"","frontmatter":{"title":"次优理论","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/theory-of-second-best.md","filePath":"econ/theory-of-second-best.md","lastUpdated":1791063341000}'),p={name:"econ/theory-of-second-best.md"};function d(C,E,h,c,m,F){const A=i("Mermaid");return B(),l("div",null,[E[2]||(E[2]=e('<h1 id="次优理论" tabindex="-1">次优理论 <a class="header-anchor" href="#次优理论" aria-label="Permalink to &quot;次优理论&quot;">​</a></h1><div class="epigraph"><p>若帕累托最优的某一条件因故无法满足，则其余条件一般也不再可欲；逐条对齐「还剩下的」一阶条件，不必改进福利。</p><footer>—— Lipsey and Lancaster, The General Theory of Second Best, Review of Economic Studies, 1956</footer></div><p><a href="/econ/deadweight-loss">上一课</a>（无谓损失）。留下楔子：商品税、要素税改净价，负担按弹性落。 <a href="/econ/welfare-theorems">第二福利定理</a>要用总额转移才能分权实现任意有效点，总额税在激励与信息上往往不可用。缺口是：已经有一块扭曲钉死，计划者还应不应该把其余市场都拉回「MRS = MRT」？Lipsey–Lancaster 说：不必。本课钉次优，然后市场失灵课序结束，博弈课序接手。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>帕累托最优是一组切条件同时成立。设其中一条因垄断、关税或无法取消的税而永久违背。直觉是：其余市场尽量竞争、尽量不征税，至少靠近最优。次优定理切断这直觉。约束下的最优（次优）一般要求其余边际也偏离它们的第一最佳值；单独消除某一个可消除的扭曲，福利可能下降。</p><p>缺口不是再算归宿，而是规范：在不能回到完整市场加总额税的制度里，「纠正看起来最像第一最佳的那一项」没有福利定理保证。</p><h3 id="次优不是「第二好的政策清单」" tabindex="-1">次优不是「第二好的政策清单」 <a class="header-anchor" href="#次优不是「第二好的政策清单」" aria-label="Permalink to &quot;次优不是「第二好的政策清单」&quot;">​</a></h3><p>名字容易读成一份具体药方。Lipsey–Lancaster 是一般命题：附加约束进入拉格朗日之后，一阶条件全部改写，交叉项把扭曲传到所有市场。没有更多结构，推不出「只对外部性征税、其余放任」一定对——尽管<a href="/econ/externality-pigou">庇古</a>在第一最佳里是对的。</p><p><span class="marginnote">次优的直觉类比：一套音响烧坏了一个喇叭，你把功放的均衡调歪去将就它。这时把其余器材一台台恢复出厂设置（逐条对齐「还好的」部件），音质不会变好，反而更怪——要动就得把功放与剩下部件调到「配套的歪」。福利同理：各条件是一套结构，不是一个清单。</span></p><p><span class="marginnote">典型反例：一个部门垄断，价格高于边际成本。另一部门若仍按边际成本定价，资源会过度流入竞争部门。次优可能要在竞争部门也加税，把相对价格扳回来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把第一最佳写成 \\(\\max W(x)\\) s.t. 资源与技术。次优再加约束 \\(g(x)=0\\)，该约束正是那条无法满足的切条件。拉格朗日对未约束变量的导数里出现 \\(\\mu\\nabla g\\)，于是其余切条件都带 \\(\\mu\\) 的修正项。除非 \\(g\\) 与这些变量可分，修正项不为零。</p><p>政策含义是比较静态，不是口号。要判断「取消一项关税」好不好，必须看它与留下的扭曲是互补还是替代。公共品融资只能用扭曲税时，萨缪尔森条件也要改写（Ramsey 加总、修正的 MRS 之和），不能直接套第一最佳的 \\(\\sum\\mathrm{MRS}=\\mathrm{MRT}\\)。</p>',13)),(B(),t(s,null,{default:a(()=>[o(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20FB%5B%22%E7%AC%AC%E4%B8%80%E6%9C%80%E4%BD%B3%EF%BC%9A%E5%85%A8%E9%83%A8%E5%88%87%E6%9D%A1%E4%BB%B6%22%5D%20--%3E%20LOCK%5B%22%E4%B8%80%E6%9D%A1%E5%88%87%E6%9D%A1%E4%BB%B6%E8%A2%AB%E9%94%81%E6%AD%BB%22%5D%0A%20%20LOCK%20--%3E%20SB%5B%22%E6%AC%A1%E4%BC%98%EF%BC%9A%E5%85%B6%E4%BD%99%E8%BE%B9%E9%99%85%E4%B9%9F%E6%94%B9%22%5D%0A%20%20SB%20--%3E%20WARN%5B%22%E5%8D%95%E7%8B%AC%E5%AF%B9%E9%BD%90%E6%9F%90%E4%B8%80%E6%9D%A1%E5%8F%AF%E8%83%BD%E6%9B%B4%E7%B3%9F%22%5D%0A%20%20WARN%20--%3E%20GAME%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%B2%A1%E6%9C%89%E8%AE%A1%E5%88%92%E8%80%85%EF%BC%8C%E5%8F%AA%E5%89%A9%E7%AD%96%E7%95%A5%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<p>本课不展开最优商品税的 Ramsey 公式细节；只要记住：楔子的最优模式由需求的替代矩阵决定，不是由「每个市场自己的弹性」单独决定——尽管 Ramsey 的简化情形看起来像逆弹性。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>扭曲通过相对价格传播。锁死的那条条件规定了某两种商品的错误比率；其他商品是否「按自己的 MRT 定价」，问的是它们相对这一错误比率是否又偏了一次。次优要的是相对价格结构，不是每一对都回到第一最佳。</p><p>这与归宿同一条一般均衡通道：税落在谁身上，取决于替代；次优的修正项，也取决于替代。归宿是实证的负担；次优是规范的「还该不该加下一根楔子」。公共品若只能用扭曲税融资，萨缪尔森加总也要乘上公共资金的边际成本，不能直接把<a href="/econ/tax-incidence">上一课</a>的楔子当零。</p><p>本课仍假定有人在解约束最优。若连这个计划者都没有，只剩厂商或消费者互为环境，解概念必须换成相互最优反应——那是下一课纳什，不是再写一条拉格朗日。</p><h3 id="何时仍可分段用第一最佳" tabindex="-1">何时仍可分段用第一最佳 <a class="header-anchor" href="#何时仍可分段用第一最佳" aria-label="Permalink to &quot;何时仍可分段用第一最佳&quot;">​</a></h3><p>若偏好在某类商品上弱可分、生产可分，锁死的扭曲不泄漏进那一块，块内切条件可以仍是第一最佳。可分是要证明的性质，不是默认。庇古税遇上其他扭曲，最优税率也不是单独的 \\(\\mathrm{MD}\\)：可能少征（已有商品税叠在同一商品上），也可能多征（替代品那边有垄断加成）。符号由交叉弹性决定。</p><p><span class="marginnote">Lipsey–Lancaster 是可能性定理：告诉你逐条矫正无依据。实证次优要估计替代矩阵，误差可以翻转政策符号。政治上「某税率为零」本身也是一条 \\(g(x)\\)，应写进约束。</span></p><p><span class="marginnote">数字实例：部门 A 垄断加价 50%，部门 B 按边际成本定价，相对价格 A/B = 1.5，资源涌向 B。若在 B 上也加 50% 的税，两个价格「都不对」，但 A/B 回到 1，相对结构反而对了——这就是「其余边际也偏离第一最佳」的含义：次优追求的是比率的对，不是每个价格各自的对。</span></p>',9)),(B(),t(s,null,{default:a(()=>[o(A,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20MON%5B%22%E9%83%A8%E9%97%A8%20A%EF%BC%9A%E5%9E%84%E6%96%AD%EF%BC%8C%E4%BB%B7%E6%A0%BC%E9%AB%98%E4%BA%8E%E8%BE%B9%E9%99%85%E6%88%90%E6%9C%AC%22%5D%20--%3E%20RATIO%5B%22A%20%E5%AF%B9%20B%20%E7%9A%84%E7%9B%B8%E5%AF%B9%E4%BB%B7%E6%A0%BC%E8%A2%AB%E6%8A%AC%E9%AB%98%22%5D%0A%20%20RATIO%20--%3E%20FLOW%5B%22%E8%B5%84%E6%BA%90%E8%BF%87%E5%BA%A6%E6%B5%81%E8%BF%9B%E6%8C%89%E8%BE%B9%E9%99%85%E6%88%90%E6%9C%AC%E5%AE%9A%E4%BB%B7%E7%9A%84%E9%83%A8%E9%97%A8%20B%22%5D%0A%20%20FLOW%20--%3E%20MIS%5B%22B%20%E7%9A%84%E3%80%8E%E6%AD%A3%E7%A1%AE%E5%AE%9A%E4%BB%B7%E3%80%8F%E6%94%BE%E8%BF%9B%E9%94%99%E8%AF%AF%E8%83%8C%E6%99%AF%EF%BC%8C%E6%88%90%E4%BA%86%E5%8F%A6%E4%B8%80%E7%A7%8D%E9%94%99%22%5D%0A%20%20MIS%20--%3E%20FIX%5B%22%E6%AC%A1%E4%BC%98%E8%A7%A3%EF%BC%9A%E5%9C%A8%20B%20%E4%B9%9F%E5%8A%A0%E4%B8%80%E9%81%93%E6%A5%94%E5%AD%90%E6%89%B3%E5%9B%9E%E6%AF%94%E7%8E%87%22%5D%0A%20%20FIX%20--%3E%20NOTE%5B%22%E4%BF%AE%E5%A4%9A%E5%B0%91%EF%BC%8C%E5%8F%96%E5%86%B3%E4%BA%8E%20A%20%E4%B8%8E%20B%20%E4%B9%8B%E9%97%B4%E7%9A%84%E6%9B%BF%E4%BB%A3%2F%E4%BA%92%E8%A1%A5%22%5D%0A%20%20NOTE%20--%3E%20SEP%7B%22%E8%8B%A5%20A%20%E4%B8%8E%20B%20%E5%8F%AF%E5%88%86%EF%BC%9F%22%7D%0A%20%20SEP%20--%3E%7C%22%E5%8F%AF%E5%88%86%EF%BC%8C%E4%BA%92%E4%B8%8D%E7%89%B5%E8%BF%9E%22%7C%20ZERO%5B%22%E4%BF%AE%E6%AD%A3%E9%A1%B9%E4%B8%BA%E9%9B%B6%EF%BC%9A%E5%9D%97%E5%86%85%E4%BB%8D%E5%8F%AF%E7%94%A8%E7%AC%AC%E4%B8%80%E6%9C%80%E4%BD%B3%22%5D%0A%20%20SEP%20--%3E%7C%22%E6%9C%89%E6%9B%BF%E4%BB%A3%E6%88%96%E4%BA%92%E8%A1%A5%22%7C%20MU%5B%22%E5%BF%85%E9%A1%BB%E5%B8%A6%E7%9D%80%20%CE%BC%20%E9%A1%B9%E9%87%8D%E5%86%99%E5%85%B6%E4%BD%99%E5%88%87%E6%9D%A1%E4%BB%B6%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>若经济可分——扭曲被关在一个与其余商品无替代、无互补的孤岛——第一最佳条件在其余处仍成立。可分是刀刃。信息不完全、数量配额、政治约束，都会制造各自的 \\(g(x)\\)，没有统一的「次优税率表」。</p><p>次优也不等于「什么都不要改」。它禁止的是无结构的逐条对齐，不是禁止计算。有了需求系统，仍可解约束最优。</p><p>Ramsey 最优商品税是次优的一个解，不是「每个市场各自按逆弹性征税」的口号；交叉弹性把楔子绑在一起。</p><p>后课离开计划者。市场失灵课序默认：第一最佳的切条件不能当清单用。策略互动里，连「谁是计划者」都不存在，解概念换成纳什。</p><p><span class="marginnote">常见误区：初学者容易把次优理论读成「反正处处是次优，改革都说不准，不如不改」。它禁止的只是<strong>无结构的逐条对齐</strong>，不是禁止计算：有了需求系统与替代矩阵，约束最优照样可以解，改革照样可以排序。次优给的是「先算再动」，不是「动不如静」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一条切条件锁死，其余第一最佳条件一般不再是约束最优。</li><li>单独消除一个扭曲，福利可能下降。</li><li>庇古、萨缪尔森在第一最佳里对；次优里要重写。</li><li>可分经济是例外，不是通例。</li><li>出处：Lipsey and Lancaster, <em>RES</em> 1956。</li></ul>',8))])}const f=n(p,[["render",d]]);export{_ as __pageData,f as default};
